// Content layer for `changelogEntry` (plan §8.3), fetched from Sanity at build
// time. Human-friendly release notes — the per-package CHANGELOG.md files
// generated by Changesets remain the machine-readable source of truth.
import type { PortableTextNode } from "./portable-text";
import { normalizeBody, sanityFetch } from "./sanity";

export interface ChangelogEntry {
  version: string;
  date: string;
  title: string;
  body: PortableTextNode[];
}

const rows = await sanityFetch<(Omit<ChangelogEntry, "body"> & { body: unknown[] | null })[]>(`
  *[_type == "changelogEntry"] | order(date desc) { version, date, title, body }
`);

const entries: ChangelogEntry[] = rows.map((row) => ({ ...row, body: normalizeBody(row.body) }));

export function getChangelogEntries(): ChangelogEntry[] {
  return [...entries].sort((a, b) => b.date.localeCompare(a.date));
}
